def topoSortBruteForce(V: int, adj: list[list[int]]) -> list[int]:
    import itertools
    # Generate all possible permutations of vertices
    for perm in itertools.permutations(range(V)):
        pos = {val: idx for idx, val in enumerate(perm)}
        possible = True
        # Check if every edge u -> v satisfies pos[u] < pos[v]
        for u in range(V):
            for v in adj[u]:
                if pos[u] > pos[v]:
                    possible = False
                    break
            if not possible:
                break
        # If permutation is valid, return it
        if possible:
            return list(perm)
    return []

