def isBipartiteBrute(graph: list[list[int]]) -> bool:
    n = len(graph)
    # Try all 2^n configurations of coloring nodes 0 and 1
    for mask in range(1 << n):
        colors = [(mask >> i) & 1 for i in range(n)]
        valid = True
        for u in range(n):
            for v in graph[u]:
                if colors[u] == colors[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            return True
    return False

from collections import deque

def isBipartite(graph: list[list[int]]) -> bool:
    n = len(graph)
    # color array: -1 means uncolored, 0/1 are the two colors
    color = [-1] * n

    # Helper BFS function
    def bfs(start):
        queue = deque([start])
        color[start] = 0 # Start by coloring the initial node with 0

        while queue:
            u = queue.popleft()
            # Check all adjacent neighbors
            for v in graph[u]:
                # If neighbor is uncolored, color with opposite color
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    queue.append(v)
                # If neighbor has the same color, graph is not bipartite
                elif color[v] == color[u]:
                    return False
        return True

    # Run BFS for each component to handle disconnected graphs
    for i in range(n):
        if color[i] == -1:
            if not bfs(i):
                return False
    return True

def shortestPathBrute(V: int, edges: list[list[int]], src: int) -> list[int]:
    adj = [[] for _ in range(V)]
    for u, v, w in edges:
        adj[u].append((v, w))
    dist = [float('inf')] * V

    def dfs(node, cur_d):
        dist[node] = min(dist[node], cur_d)
        for neighbor, weight in adj[node]:
            dfs(neighbor, cur_d + weight)

    dfs(src, 0)
    return [d if d != float('inf') else -1 for d in dist]

def shortestPathInDAG(V: int, edges: list[list[int]], src: int) -> list[int]:
    # Create adjacency list representation
    adj = [[] for _ in range(V)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Step 1: Find topological sort using DFS
    visited = [False] * V
    stack = []

    def topo_dfs(node):
        visited[node] = True
        for neighbor, _ in adj[node]:
            if not visited[neighbor]:
                topo_dfs(neighbor)
        stack.append(node)

    for i in range(V):
        if not visited[i]:
            topo_dfs(i)

    # Step 2: Initialize distances to infinity
    dist = [float('inf')] * V
    dist[src] = 0

    # Step 3: Relax edges in topological order
    while stack:
        u = stack.pop()
        if dist[u] != float('inf'):
            for v, w in adj[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

    # Replace infinity with -1 for unreachable nodes
    return [d if d != float('inf') else -1 for d in dist]

def dijkstraBruteForce(V: int, adj: list[list[list[int]]], src: int) -> list[int]:
    dist = [float('inf')] * V
    visited = [False] * V
    dist[src] = 0

    for _ in range(V):
        # Find unvisited vertex with minimum distance
        u = -1
        min_d = float('inf')
        for i in range(V):
            if not visited[i] and dist[i] < min_d:
                min_d = dist[i]
                u = i
        if u == -1:
            break
        visited[u] = True
        # Update distances of adjacent vertices
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist

