def bellmanFord(V: int, edges: list[list[int]], src: int) -> list[int]:
    # Use 1e8 to represent infinity to prevent overflow when adding weights
    INF = 10**8
    dist = [INF] * V
    dist[src] = 0

    # Relax all edges V-1 times
    for _ in range(V - 1):
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # V-th iteration to detect negative cycle
    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v]:
            # Negative cycle found, return [-1]
            return [-1]

    return dist

