def floydWarshall(matrix: list[list[int]]) -> None:
    V = len(matrix)
    INF = 1e9

    # Replace -1 (no path) with INF for calculations
    for i in range(V):
        for j in range(V):
            if matrix[i][j] == -1:
                matrix[i][j] = INF
            if i == j:
                matrix[i][j] = 0

    # Try each vertex as an intermediate node k
    for k in range(V):
        for i in range(V):
            for j in range(V):
                # Update the path if routing through k is shorter
                matrix[i][j] = min(matrix[i][j], matrix[i][k] + matrix[k][j])

    # Replace remaining INF values back to -1
    for i in range(V):
        for j in range(V):
            if matrix[i][j] >= INF:
                matrix[i][j] = -1

