class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    # Find operation with path compression
    def find(self, i):
        if self.parent[i] == i:
            return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    # Union operation by rank
    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            if self.rank[root_i] < self.rank[root_j]:
                self.parent[root_i] = root_j
            elif self.rank[root_i] > self.rank[root_j]:
                self.parent[root_j] = root_i
            else:
                self.parent[root_j] = root_i
                self.rank[root_i] += 1
            return True
        return False

def spanningTreeKruskal(V: int, edges: list[list[int]]) -> int:
    # Sort edges based on weight
    edges.sort(key=lambda x: x[2])
    dsu = DisjointSet(V)
    mst_weight = 0

    for u, v, w in edges:
        # If endpoints are in different components, union them and add weight
        if dsu.union(u, v):
            mst_weight += w

    return mst_weight

def maxNonAdjacentSumBrute(nums: list[int]) -> int:
    def helper(idx):
        # Base case: index out of bounds
        if idx >= len(nums):
            return 0
        # Choice 1: Include current element and skip next
        pick = nums[idx] + helper(idx + 2)
        # Choice 2: Exclude current element
        skip = helper(idx + 1)
        return max(pick, skip)
    return helper(0)

def robBrute(nums: list[int]) -> int:
    def helper(idx):
        if idx >= len(nums):
            return 0
        return max(nums[idx] + helper(idx + 2), helper(idx + 1))
    return helper(0)

def canCrossBrute(stones: list[int]) -> bool:
    stone_set = set(stones)
    target = stones[-1]

    def helper(curr, k):
        # Base case: reached target stone
        if curr == target:
            return True
        # Try all 3 possible next jumps: k-1, k, k+1
        for j in (k - 1, k, k + 1):
            if j > 0 and (curr + j) in stone_set:
                if helper(curr + j, j):
                    return True
        return False

    if stones[1] != 1:
        return False
    return helper(1, 1)

def canCross(stones: list[int]) -> bool:
    # dp maps each stone position to a set of jump sizes that can reach it
    dp = {stone: set() for stone in stones}
    # Base case: 0 jump size reaches stone 0
    dp[0].add(0)

    for stone in stones:
        # Process each jump size that reached the current stone
        for k in dp[stone]:
            # Try step sizes: k-1, k, k+1
            for step in (k - 1, k, k + 1):
                # Jump must be positive and land on an existing stone
                if step > 0 and (stone + step) in dp:
                    dp[stone + step].add(step)

    # If the last stone has any incoming jumps, crossing is possible
    return len(dp[stones[-1]]) > 0

def minimizeCostBrute(heights: list[int], K: int) -> int:
    def helper(idx):
        if idx == 0:
            return 0
        min_cost = float('inf')
        for j in range(1, K + 1):
            if idx - j >= 0:
                cost = helper(idx - j) + abs(heights[idx] - heights[idx - j])
                min_cost = min(min_cost, cost)
        return min_cost
    return helper(len(heights) - 1)

def climbStairsBrute(n: int) -> int:
    # Recursive relation: F(n) = F(n-1) + F(n-2)
    if n <= 1:
        return 1
    return climbStairsBrute(n - 1) + climbStairsBrute(n - 2)

def coinChangeBrute(coins: list[int], amount: int) -> int:
    def helper(rem):
        if rem == 0:
            return 0
        if rem < 0:
            return float('inf')
        min_coins = float('inf')
        for coin in coins:
            res = helper(rem - coin)
            if res != float('inf'):
                min_coins = min(min_coins, 1 + res)
        return min_coins
    ans = helper(amount)
    return ans if ans != float('inf') else -1
